// ===== Préparer le fichier =====
// Le formulaire nomme la pièce jointe d'après le libellé du champ.
// On la renomme en « data » pour que l'étape Extraction la trouve toujours,
// et on calcule l'identifiant du livre (book_id) à partir de son titre :
// minuscules, sans accents ni ponctuation, sans ce qui est entre parenthèses.
// « Introduction to Business (OpenStax, CC BY 4.0) » → introduction-to-business
// Le book_id préfixe chaque chunk_id : deux livres ne peuvent plus se marcher dessus,
// et redéposer le même livre (même titre) reprend l'indexation là où elle s'était arrêtée.
const item = $input.first();
const keys = Object.keys(item.binary || {});
if (!keys.length) throw new Error('Aucun PDF reçu depuis le formulaire.');
const file = item.binary[keys[0]];

const title = String(item.json['Titre du livre'] ?? '').replace(/\s+/g, ' ').trim();
if (!title) throw new Error('Indique le titre du livre dans le formulaire.');
const bookId = title
  .replace(/\(.*?\)/g, ' ')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  .slice(0, 40).replace(/-+$/, '');
if (!bookId) throw new Error(`Titre de livre inutilisable : « ${title} ».`);

return [{ json: { file_name: file.fileName || 'livre.pdf', book_title: title, book_id: bookId }, binary: { data: file } }];

// ===== Étape CLEANING (structuration + nettoyage, avant le chunking) =====
// Code node, mode "Run Once for All Items"
// Entrée : sortie de « Extraction » (Extract from File, joinPages = false) → $json.text = tableau de pages.
// 1. Structure le texte brut en Markdown :
//    - « # N Titre » / « ## N.0 … » au début de chaque chapitre (page « Introduction » ou ligne « Chapter N ») ;
//    - « ## N.M Titre » pour chaque section numérotée, uniquement DANS L'ORDRE (ignore sommaire et tableaux) ;
//    - « # Appendix X | … » et « # References » après le dernier chapitre.
// 2. Retire le bruit de mise en page sans toucher aux titres ni aux séparateurs de page « --- » :
//    en-têtes et pieds de page répétés (repérés automatiquement), numéros de page, crédits, filigranes.
// Fonctionne pour d'autres livres : sections numérotées « 3.2 », chapitres « Chapter 3 », ou rien du tout
// (le Chunking découpe alors par pages).

const NOISE_LINES = [
  /^this openstax book is available for free at/i,   // pied de page OpenStax
  /^access for free at openstax\.org/i,
  /^download for free at/i,
  /^chapter \d{1,2} [a-z].*$/i,                       // en-tête courant « Chapter 5 Entrepreneurship… »
  /^appendix [a-z] \|.*$/i,                           // en-tête courant d'une annexe
  /^\d{1,4}$/,                                       // numéro de page seul
  /^figure \d+\.\d+.*credit.*$/i,                    // crédits photo des figures
  /oceanofpdf/i,                                     // filigrane de site de téléchargement
];
const INLINE = [
  /(\bThis\s+)?OpenStax book is available(\s+for\s+free\s+at)?(\s+https?:\/\/\S*)?/gi,
  /Access for free at openstax\.org\.?/gi,
  /Download for free at\s+\S+/gi,
  /\s?\[\d{1,3}\](?=[\s.,;:!?)]|$)/g,               // renvois numérotés vers la liste des sources « [78] »
];

const isHeading = (l) => /^#{1,6}\s/.test(l);
const isPageBreak = (l) => /^\s*---\s*$/.test(l);
const nonEmpty = (p) => String(p ?? '').split('\n').map(l => l.trim()).filter(Boolean);

// ---------- Structuration : texte brut d'« Extract from File » → Markdown à titres ----------
// Passe 1 : repère les sections numérotées dans l'ordre (pour savoir quel est le dernier chapitre
// et quels chapitres ont des sections). Passe 2 : écrit le Markdown.
function structure(pages, plan) {
  let last = [0, 0];
  const seen = new Set();          // sections « N.M » acceptées
  const appendixDone = new Set();
  let refsDone = false;
  const lastChapter = plan ? plan.lastChapter : Infinity;
  const isNext = (c, s) =>
    (last[0] === 0 && c === 1 && (s === 1 || s === 0)) ||
    (c === last[0] && (s === last[1] + 1 || s === last[1] + 2)) ||
    (c === last[0] + 1 && (s === 1 || s === 0));
  const afterBook = () => last[0] >= lastChapter;      // dernier chapitre atteint (annexes, références)

  const out = pages.map(p => {
    const ls = String(p ?? '').split('\n');
    const res = [];
    const top = nonEmpty(p);
    let k0 = 0;

    // Début de chapitre, cas 1 : la page commence par « Introduction » et le chapitre suivant a des sections
    // numérotées (livres OpenStax et manuels du même type).
    const next = last[0] + 1;
    if (plan && next <= lastChapter && top[0] === 'Introduction' && plan.seen.has(`${next}.1`) && (last[0] === 0 || last[1] >= 1)) {
      res.push(`## ${next}.0 Introduction`);
      last = [next, 0];
      k0 = ls.findIndex(l => l.trim() === 'Introduction') + 1;
    }
    // Début de chapitre, cas 2 : ligne « Chapter N » / « Chapitre N » (seule ou suivie du titre) en haut de page.
    if (next <= lastChapter && k0 === 0) {     // aussi en passe 1, pour connaître le dernier chapitre
      for (let t = 0; t < Math.min(4, top.length); t++) {
        const m = top[t].match(/^(?:chapter|chapitre)\s+(\d{1,2})\s*(?:[:.\-–—]\s*)?([A-ZÀ-Ý].{2,120})?$/i);
        if (!m || +m[1] !== next || (m[2] && /\s\d{1,4}$/.test(top[t]))) continue;   // « Titre 123 » = sommaire / en-tête
        const title = (m[2] || top[t + 1] || '').trim();
        res.push(`# ${next} ${title}`);
        res.push(`## ${next}.0 ${plan && plan.seen.has(`${next}.1`) ? 'Introduction' : title}`);
        last = [next, 0];
        const idx = ls.findIndex(l => l.trim() === top[t]);
        k0 = idx + 1 + (m[2] ? 0 : 1);
        break;
      }
    }

    for (let k = k0; k < ls.length; k++) {
      const t = ls[k].trim();
      let m = t.match(/^(\d{1,2})\.(\d{1,2})$/);
      if (m && isNext(+m[1], +m[2]) && +m[2] > 0) {
        const j = ls.slice(k + 1, k + 6).findIndex(x => x.trim() && !/^[\d.]+$/.test(x.trim()));
        if (j >= 0) {
          res.push(`## ${m[1]}.${m[2]} ${ls[k + 1 + j].trim()}`);
          last = [+m[1], +m[2]]; seen.add(`${m[1]}.${m[2]}`);
          k = k + 1 + j;
          continue;
        }
      }
      m = t.match(/^(\d{1,2})\.(\d{1,2})\s+([A-Z][^\n•]{3,120})$/);
      if (m && !/\s\d{1,4}$/.test(t) && isNext(+m[1], +m[2]) && +m[2] > 0) {
        res.push(`## ${m[1]}.${m[2]} ${m[3].trim()}`);
        last = [+m[1], +m[2]]; seen.add(`${m[1]}.${m[2]}`);
        continue;
      }
      if (plan && afterBook()) {
        const a = t.match(/^Appendix\s+([A-Z])\b\s*[|:.\-–—]?\s*(.*)$/);
        if (a && !appendixDone.has(a[1])) { res.push(`# Appendix ${a[1]} | ${a[2].replace(/[*\s]*\d{0,4}\s*$/, '').trim()}`); appendixDone.add(a[1]); continue; }
        if (!refsDone && /^(References|Bibliography|Index)$/.test(t)) { res.push('# References'); refsDone = true; continue; }
      }
      res.push(ls[k]);
    }
    return res.join('\n');
  });
  return { md: out.join('\n\n---\n\n'), seen, lastChapter: last[0] };
}

// ---------- Structuration par le SOMMAIRE (livres sans numéros : essais, guides…) ----------
// Utilisé seulement si la passe 1 n'a trouvé ni « Chapter N » ni section « N.M ».
// 1. Lit le sommaire (« Contents », « Table of Contents », « Sommaire »…) au début du livre :
//    « PART I: … » = partie, ligne EN MAJUSCULES = chapitre, autre ligne = section du chapitre,
//    « Appreciation / Sources / About the author… » = fin du livre (non indexée).
// 2. Retrouve ces titres DANS L'ORDRE dans le texte (un titre peut être coupé sur 2-3 lignes)
//    et écrit « # N Titre », « ## N.0 Titre », « ## N.M Section » comme pour un livre numéroté.
// Les numéros N / N.M sont internes (ordre, identifiants, filtres) : les citations montrent les titres.
const norm = (s) => String(s).normalize('NFKD').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
const SMALL = new Set(['a', 'an', 'and', 'as', 'at', 'by', 'for', 'in', 'of', 'on', 'or', 'the', 'to', 'vs']);
const titleCase = (s) => s.toLowerCase().split(' ')
  .map((w, i) => (i > 0 && SMALL.has(w) ? w : w.replace(/^([("“'‘]?)(\p{L})/u, (_, a, b) => a + b.toUpperCase())))
  .join(' ');
const END_MATTER = /^(appreciation|acknowledge?ments?|sources|notes|endnotes|references|bibliography|index|about the authors?)$/i;

function tocStructure(pages) {
  // --- 1. le sommaire ---
  const flat = [];                                   // lignes non vides : { page, text }
  pages.forEach((p, pi) => nonEmpty(p).forEach(t => flat.push({ page: pi, text: t })));
  const limit = Math.max(10, Math.ceil(pages.length * 0.1));
  const start = flat.findIndex(l => l.page < limit && /^(contents|table of contents|sommaire|table des matières)$/i.test(l.text));
  if (start < 0) return null;

  const entries = [];
  let k = start + 1;
  for (; k < flat.length && flat[k].page <= flat[start].page + 4; k++) {
    const t = flat[k].text.replace(/[\s.·…]*\d{1,4}$/, '').trim();       // « Titre ..... 12 » → « Titre »
    if (!t || t.length > 90 || /[.!?]$/.test(t) && !/…$/.test(flat[k].text)) break;   // une phrase = le livre a commencé
    if (entries.length >= 3) {                       // le 1er titre réapparaît (coupé ou non) : fin du sommaire
      const first = norm(entries[0]);
      const w = norm(t) + norm(flat[k + 1]?.text || '') + norm(flat[k + 2]?.text || '');
      if (first.length > 3 && w.startsWith(first) && norm(t).length < first.length + 1) break;
    }
    entries.push(t);
  }
  const bodyStart = k;

  // Ligatures « fi » / « fl » mal extraites du PDF : « Specif ic » → « Specific »
  // (on recolle seulement si le mot entier est plus fréquent dans le livre que le morceau seul)
  const freq = new Map();
  for (const l of flat) for (const w of l.text.toLowerCase().match(/[a-z]+/g) || []) freq.set(w, (freq.get(w) || 0) + 1);
  const fixLig = (s) => s.replace(/\b([A-Za-z]*f) ([il][a-z]+)\b/g, (m, a, b) =>
    ((freq.get((a + b).toLowerCase()) || 0) > (freq.get(b.toLowerCase()) || 0) ? a + b : m));
  for (let i = 0; i < entries.length; i++) entries[i] = fixLig(entries[i]);

  let part = '', chapter = 0, section = 0, ended = false;
  const plan = [];                                   // titres attendus dans le corps, dans l'ordre
  for (const e of entries) {
    if (ended) break;
    const pm = e.match(/^part\s+([ivx]+|\d+)\b[\s:.\-–—]*(.*)$/i);
    if (END_MATTER.test(e)) { plan.push({ kind: 'end', text: e }); ended = true; }
    else if (pm) { part = `Part ${pm[1].toUpperCase()}${pm[2] ? ': ' + titleCase(pm[2]) : ''}`; plan.push({ kind: 'part', text: e }); }
    else if (!/\p{Ll}/u.test(e)) {                   // EN MAJUSCULES = chapitre
      if (/^(bonus|appendix|appendices|annexes?)\b/i.test(e)) part = '';
      chapter++; section = 0;
      plan.push({ kind: 'chapter', text: e, n: chapter, title: titleCase(e), part });
    } else if (chapter > 0) {
      section++;
      plan.push({ kind: 'section', text: e, n: chapter, s: section, title: e });
    }
  }
  if (plan.filter(x => x.kind === 'chapter').length < 2) return null;

  // --- 2. les titres dans le corps du livre ---
  const titles = {}, parts = {}, missing = [];
  let next = 0;
  const out = pages.map(() => []);
  const consumed = new Set();
  for (let i = bodyStart; i < flat.length; i++) {
    let hit = null;
    for (let j = next; j < Math.min(plan.length, next + 4) && !hit; j++) {
      const target = norm(plan[j].text);
      let raw = '', w = '';
      for (let n = 0; n < 3 && i + n < flat.length; n++) {
        raw += (n ? ' ' : '') + flat[i + n].text; w += norm(flat[i + n].text);
        const sameCase = !/\p{Ll}/u.test(raw) || raw.replace(/\s+/g, ' ') === plan[j].text;
        if (w === target && sameCase) { hit = { j, len: n + 1 }; break; }
        if (!target.startsWith(w)) break;
      }
    }
    if (hit) {
      for (let j = next; j < hit.j; j++) missing.push(plan[j].text);
      const e = plan[hit.j];
      const pg = flat[i].page;
      if (e.kind === 'chapter') {
        titles[e.n] = e.title; parts[e.n] = e.part;
        out[pg].push(`# ${e.n} ${e.title}`, `## ${e.n}.0 ${e.title}`);
      } else if (e.kind === 'section') out[pg].push(`## ${e.n}.${e.s} ${e.title}`);
      else if (e.kind === 'end') out[pg].push('# References');
      for (let n = 0; n < hit.len; n++) consumed.add(i + n);
      next = hit.j + 1;
      i += hit.len - 1;
      continue;
    }
    if (!consumed.has(i)) out[flat[i].page].push(flat[i].text);
  }
  // les pages du sommaire et de la couverture restent (texte avant le 1er titre : ignoré par le Chunking)
  for (let i = 0; i < bodyStart; i++) out[flat[i].page].unshift(flat[i].text);
  return { md: out.map(ls => ls.join('\n')).join('\n\n---\n\n'), titles, parts, missing, found: next };
}

// En-têtes / pieds de page répétés : une ligne (chiffres retirés) présente en haut ou en bas
// d'au moins 10 % des pages (et au moins 5 pages) est du bruit de mise en page.
function repeatedEdges(pages) {
  const norm = (l) => l.replace(/\d+/g, '#').replace(/\s+/g, ' ').trim().toLowerCase();
  const count = new Map();
  for (const p of pages) {
    const ls = nonEmpty(p);
    const edges = new Set([...ls.slice(0, 2), ...ls.slice(-2)].map(norm).filter(x => x.length > 3));
    for (const e of edges) count.set(e, (count.get(e) || 0) + 1);
  }
  const min = Math.max(5, Math.ceil(pages.length * 0.10));
  return { norm, set: new Set([...count].filter(([, n]) => n >= min).map(([e]) => e)) };
}

let removed = 0;
let mode = 'numérotée', tocTitles = null, tocParts = {}, tocMissing = [];
const out = $input.all().map(item => {
  const src = item.json.text;
  let raw, edges = { norm: (x) => x, set: new Set() };
  if (Array.isArray(src)) {
    const plan = structure(src, null);             // passe 1
    const toc = plan.lastChapter === 0 && plan.seen.size === 0 ? tocStructure(src) : null;
    if (toc) {                                     // livre sans numéros : structure lue dans le sommaire
      raw = toc.md; mode = 'sommaire'; tocTitles = toc.titles; tocParts = toc.parts; tocMissing = toc.missing;
    } else {
      raw = structure(src, plan).md;               // passe 2
      mode = plan.lastChapter > 0 ? 'numérotée' : 'pages';
    }
    edges = repeatedEdges(src);
  } else {
    raw = String(src ?? '');                       // texte déjà en Markdown : gardé tel quel
  }
  const before = raw.length;

  const lines = raw.split('\n').filter(l => {
    if (isHeading(l) || isPageBreak(l)) return true;          // on garde toujours titres et sauts de page
    const t = l.replace(/\*\*/g, '').trim();
    if (edges.set.has(edges.norm(t))) return false;
    return !NOISE_LINES.some(re => re.test(t));
  });

  // En-têtes courants collés au milieu d'une ligne (« … 170 Chapter 5 Entrepreneurship: … ») :
  // on lit les titres de chapitre, puis on les retire en ligne.
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
  // Priorité 1 : lignes explicites « Chapter N Titre » ; priorité 2 : titres Markdown « # N Titre ».
  const titles = {};
  const allLines = raw.split('\n');
  for (const l of allLines) {
    const t = l.replace(/^#{1,6}\s*/, '').replace(/\*\*/g, '').trim();
    const m = t.match(/^Chapter\s+(\d{1,2})\s+([A-Z][^\n]{3,140})$/);
    if (m && !titles[m[1]]) titles[m[1]] = m[2].replace(/\s+\d{1,4}$/, '').trim();
  }
  for (const l of allLines) {
    if (!isHeading(l)) continue;
    const t = l.replace(/^#{1,6}\s*/, '').replace(/\*\*/g, '').trim();
    const m = t.match(/^(\d{1,2})\s+([A-Z][^\n]{3,140})$/);
    if (m && !titles[m[1]]) titles[m[1]] = m[2].replace(/\s+\d{1,4}$/, '').trim();
  }
  const inlineHeaders = Object.entries(titles).map(([n, t]) =>
    new RegExp(`(\\b\\d{1,4}\\s+)?Chapter\\s+${n}\\s+${esc(t)}(\\s+\\d{1,4}\\b)?`, 'g'));
  for (const l of allLines) {
    const a = l.match(/^# Appendix ([A-Z]) \| (.+)$/);
    if (a) inlineHeaders.push(new RegExp(`(\\b\\d{1,4}\\s+)?Appendix ${a[1]} \\|\\s+${esc(a[2].trim())}(\\s+\\d{1,4}\\b)?`, 'g'));
  }

  let text = lines
    .map(l => (isHeading(l) ? l : inlineHeaders.reduce((acc, re) => acc.replace(re, ' '), l)))
    .join('\n');
  for (const re of INLINE) text = text.replace(re, ' ');
  text = text
    .replace(/(\w)-\n(\w)/g, '$1$2')     // recolle les mots coupés « busi-\nness »
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n');

  removed += before - text.length;
  // titres de chapitre lus AVANT suppression des en-têtes courants : transmis au Chunking en secours
  if (tocTitles) Object.assign(titles, tocTitles);
  return { json: { text, structure: mode, chapter_titles: titles, chapter_parts: tocParts, titres_introuvables: tocMissing, caracteres_avant: before, caracteres_apres: text.length } };
});

return out;

// ===== Découpage aux titres (H1 / H2) + Recursive Character Text Splitter (5 000, sans overlap) =====
// Code node, mode "Run Once for All Items"
// Entrée : sortie de « Cleaning » → $json.text = Markdown du livre, pages séparées par une ligne « --- ».
// Règle du prof :
//   - # (H1) = chapitre, ## (H2) = section → on coupe d'abord aux titres ;
//   - aucun morceau ne dépasse 5 000 caractères : une section trop longue est
//     recoupée récursivement (paragraphes → lignes → phrases → mots).
// Sécurité : on ne retient que les titres NUMÉROTÉS et DANS L'ORDRE
// (1.0 → 1.1 → 1.2 → 2.0 → 2.1…), car certaines légendes ressemblent à des titres.
// N.0 = introduction du chapitre (ou chapitre entier pour un livre sans sections numérotées).
// Livre sans aucun titre repérable : découpage de secours par pages (section « p »).
// Sortie : 1 item par chunk { text, part, chapter, chapter_title, section, section_title, structure, page, chunk_index }
//          + un item de bilan en tête est inutile : le bilan est dans « Bilan ».

const CHUNK_SIZE = 5000;
const CHUNK_OVERLAP = 0;   // pas de chevauchement (choix du projet)
const SEPARATORS = ['\n## ', '\n### ', '\n#### ', '\n\n', '\n', '. ', ' ', ''];

// ---------- 1. Texte complet + repérage des pages ----------
const md = $input.all().map(i => String(i.json.text ?? '')).join('\n\n---\n\n');
const lines = md.split('\n');
let page = 1;
const linePage = lines.map(l => (/^\s*---\s*$/.test(l) ? ++page : page));

// ---------- 2. Titres numérotés, dans l'ordre ----------
const clean = (l) => l.replace(/^#{1,6}\s*/, '').replace(/\*\*/g, '').replace(/<[^>]+>/g, '').trim();
const H1 = /^(?:Chapter\s+)?(\d{1,2})\s+([A-Z][^\n]{3,140})$/;          // « 1 Understanding … » ou « Chapter 1 … »
const H2 = /^(\d{1,2})\.(\d{1,2})\s+([A-Z][^\n]{2,140})$/;              // « 1.1 The Nature of Business »
const STOP = /^(References|Bibliography|Index)$/;

const chapterTitles = {};
// Secours : titres transmis par le Cleaning (lus dans les en-têtes courants « Chapter N … »),
// pour les chapitres dont l'OCR n'a pas sorti de titre #.
const fallbackTitles = $input.first().json.chapter_titles || {};
const chapterParts = $input.first().json.chapter_parts || {};   // « Part I: Wealth » (livres structurés par sommaire)
let STRUCTURE = $input.first().json.structure || 'numérotée';
let last = [0, 0];
let stopped = false;
const sections = [];
let cur = null;

const isNextSection = (c, s) =>
  (c === last[0] && (s === last[1] + 1 || s === last[1] + 2)) ||
  (c === last[0] + 1 && (s === 0 || s === 1)) ||
  (last[0] === 0 && c === 1 && (s === 0 || s === 1));

for (let i = 0; i < lines.length && !stopped; i++) {
  const raw = lines[i];
  const isHeading = /^#{1,6}\s/.test(raw);
  const t = clean(raw);

  if (isHeading && STOP.test(t) && last[0] >= 1) { stopped = true; break; }

  if (isHeading) {
    let m = t.match(H2);
    if (m && !/\s\d{1,4}$/.test(t) && isNextSection(+m[1], +m[2])) {
      if (cur) sections.push(cur);
      last = [+m[1], +m[2]];
      cur = { chapter: +m[1], section: `${m[1]}.${m[2]}`, section_title: m[3].trim(), lines: [] };
      continue;
    }
    m = t.match(H1);
    if (m && (+m[1] === last[0] + 1 || +m[1] === last[0]) && !chapterTitles[m[1]]) {
      chapterTitles[m[1]] = m[2].replace(/\s+\d{1,4}$/, '').trim();
      continue; // le titre de chapitre ne crée pas de section : la 1re section suit
    }
    const ap = t.match(/^Appendix ([A-Z])\b\s*[|:]?\s*(.*)$/i);
    if (ap && last[0] >= 1) {
      const L = ap[1].toUpperCase();
      if (cur && cur.section === L) continue;     // en-tête courant répété sur chaque page de l'annexe
      if (cur) sections.push(cur);
      cur = { chapter: L, section: L, section_title: ap[2].trim() || `Appendix ${L}`, lines: [] };
      continue;
    }
  }
  if (cur && !/^\s*---\s*$/.test(raw)) cur.lines.push({ line: raw, page: linePage[i] });
}
if (cur) sections.push(cur);

// Secours : aucun titre repérable (roman, essai…) → tout le livre en une pseudo-section « p »,
// découpée par le Recursive Character Text Splitter ; chaque chunk garde sa page de début.
if (!sections.length) {
  const all = lines.map((line, i) => ({ line, page: linePage[i] })).filter(l => !/^\s*---\s*$/.test(l.line));
  sections.push({ chapter: '', section: 'p', section_title: '', lines: all });
  STRUCTURE = 'pages';
}

// ---------- 3. Recursive Character Text Splitter (même algorithme que LangChain / n8n) ----------
// On essaie les séparateurs du plus « gros » au plus fin : ## → ### → paragraphe → ligne → phrase → mot.
// On ne coupe jamais au milieu d'un mot tant qu'un séparateur plus gros suffit.
function splitRecursive(text, seps) {
  if (text.length <= CHUNK_SIZE) return [text];
  const sep = seps.find(s => s === '' || text.includes(s));
  const rest = seps.slice(seps.indexOf(sep) + 1);
  const parts = sep === ''
    ? Array.from({ length: Math.ceil(text.length / CHUNK_SIZE) }, (_, k) => text.slice(k * CHUNK_SIZE, (k + 1) * CHUNK_SIZE))
    : text.split(sep).map((p, k) => (k === 0 ? p : sep + p));
  const out = [];
  let buf = '';
  for (const p of parts) {
    if (p.length > CHUNK_SIZE) {
      if (buf) { out.push(buf); buf = ''; }
      out.push(...splitRecursive(p, rest));
    } else if ((buf + p).length > CHUNK_SIZE) {
      out.push(buf);
      buf = CHUNK_OVERLAP > 0 ? buf.slice(-CHUNK_OVERLAP) + p : p;   // slice(-0) renverrait tout : on l'évite
      if (buf.length > CHUNK_SIZE) buf = p;
    } else {
      buf += p;
    }
  }
  if (buf.trim()) out.push(buf);
  return out.filter(c => c.trim());
}

// ---------- 4. Un item par chunk ----------
const items = [];
const nextIndex = {};   // compteur par section sur tout le livre → chunk_id toujours unique
for (const s of sections) {
  const text = s.lines.map(l => l.line).join('\n').trim();
  if (!text) continue;
  const chunks = splitRecursive(text, SEPARATORS);
  let offset = 0, cursor = 0;   // cursor : on cherche le chunk suivant APRÈS le précédent (les chunks se suivent)
  chunks.forEach((c, idx) => {
    // page du début du chunk : on cherche la ligne correspondante
    const pos = text.indexOf(c.slice(0, 80), Math.max(0, cursor - CHUNK_OVERLAP));
    if (pos >= 0) { offset = pos + (c.length - c.trimStart().length); cursor = pos + Math.max(1, c.length - 200); }   // page du 1er caractère non vide
    let acc = 0, p = s.lines.length ? s.lines[0].page : 1;
    for (const l of s.lines) { if (acc + l.line.length + 1 > offset) { p = l.page; break; } acc += l.line.length + 1; }
    items.push({
      json: {
        text: c,
        chapter: s.chapter,
        chapter_title: /^[A-Z]$/.test(String(s.chapter)) ? `Appendix ${s.chapter}` : (chapterTitles[s.chapter] || fallbackTitles[s.chapter] || ''),
        part: chapterParts[s.chapter] || '',
        section: s.section,
        section_title: s.section_title,
        structure: STRUCTURE,
        page: p,
        chunk_index: (nextIndex[s.section] = (nextIndex[s.section] ?? -1) + 1),
      },
    });
  });
}

if (!items.length) {
  throw new Error("Aucun texte exploitable : le PDF est peut-être scanné (images sans texte). Vérifie la sortie du nœud « Extraction ».");
}
return items;

// ===== Étape AUGMENTATION (métadonnées) =====
// Code node, mode "Run Once for All Items"
// Ajoute à chaque chunk un en-tête lisible (utile pour l'embedding et la citation)
// et les métadonnées qui seront stockées dans Supabase.
// Le titre et l'identifiant du livre viennent du formulaire (nœud « Préparer le fichier »).

const prep = $('Préparer le fichier').first().json;
const BOOK = prep.book_title;
const BOOK_ID = prep.book_id;

return $input.all().map((item, i) => {
  const j = item.json;
  const isAppendix = /^[A-Z]$/.test(String(j.chapter));
  const parts = [BOOK];
  if (j.structure === 'sommaire') {
    // Livre sans numéros : on cite les titres du livre (« Part I: Wealth › Building Wealth | How to Get Lucky »)
    parts.push([j.part, j.chapter_title].filter(Boolean).join(' › '));
    if (j.section && !/\.0$/.test(j.section)) parts.push(j.section_title);
  } else if (isAppendix) parts.push(`Appendix ${j.chapter}`);
  else if (j.chapter !== '' && j.chapter != null) parts.push(`Chapter ${j.chapter}${j.chapter_title ? ' — ' + j.chapter_title : ''}`);
  if (j.structure !== 'sommaire' && j.section && j.section !== 'p') parts.push(`Section ${j.section} — ${j.section_title}`);
  parts.push(`p. ${j.page}`);
  const header = `[${parts.join(' | ')}]`;

  return {
    json: {
      content: `${header}\n${j.text}`,
      book: BOOK,
      book_id: BOOK_ID,
      part: j.part ?? '',
      chapter: String(j.chapter ?? ''),
      chapter_title: j.chapter_title ?? '',
      section: String(j.section ?? ''),
      section_title: j.section_title ?? '',
      structure: j.structure ?? 'numérotée',
      page: String(j.page),
      chunk_id: `${BOOK_ID}:${j.section}-${j.chunk_index}`,
      global_index: String(i),
    },
  };
});

// ===== Filtrer les chunks déjà indexés (ingestion reprenable) =====
// Code node, mode "Run Once for All Items"
// « Déjà indexés » a lu dans Supabase la liste des chunk_id présents (vue indexed_chunks).
// On ne garde que les chunks manquants : relancer l'ingestion après une coupure
// (quota Gemini, timeout n8n…) reprend là où elle s'était arrêtée, sans doublon.

const done = new Set(
  $('Déjà indexés').all()
    .map(item => item.json && item.json.chunk_id)
    .filter(Boolean)
);

const all = $('Augmentation (métadonnées)').all();
const todo = all.filter(item => !done.has(item.json.chunk_id));

// Rien à faire : on s'arrête proprement (aucun item → la boucle ne tourne pas).
return todo;

// ===== Bilan =====
// Code node, mode "Run Once for All Items" : volume traité par ce run, pour CE livre.
const prep = $('Préparer le fichier').first().json;
const ids = new Set($('Augmentation (métadonnées)').all().map(i => i.json.chunk_id));
const total = ids.size;
const deja = $('Déjà indexés').all().filter(i => i.json && ids.has(i.json.chunk_id)).length;   // de ce livre seulement
const autres = $('Déjà indexés').all().filter(i => i.json && i.json.chunk_id && !ids.has(i.json.chunk_id)).length;
const envoyes = $('Limite (chunks par exécution)').all().length;     // chunks du lot
const augmentes = $('Assembler les chunks augmentés').all().length;  // augmentation IA lisible
const faits = $input.all().filter(i => i.json && i.json.statut === 'indexé').length;
const restants = Math.max(0, total - deja - faits);
return [{ json: {
  livre: prep.book_title,
  livre_id: prep.book_id,
  chunks_du_livre: total,
  deja_indexes_avant: deja,
  lot_ce_run: envoyes,
  augmentes_ce_run: augmentes,
  indexes_ce_run: faits,
  restants,
  autres_chunks_en_base: autres,
  statut: restants === 0
    ? 'Livre entièrement indexé'
    : (deja === 0 && autres > 0
      ? `Nouveau livre « ${prep.book_id} » : si c'est un livre déjà commencé, le titre ne correspond pas (redépose avec le même titre)`
      : 'Lot terminé : redépose le PDF (même titre) pour indexer la suite, ou augmente la limite dans le nœud « Limite »'),
} }];

// ===== Assembler les chunks augmentés (étape AUGMENTATION, après « Augmentation IA (Gemini) ») =====
// Code node, mode "Run Once for All Items"
// Pour chaque chunk du lot, lit le JSON produit par Gemini (contexte, questions hypothétiques,
// mots-clés, entités, relations) et construit le texte qui sera vectorisé :
//   en-tête + augmentations EN TÊTE (jamais tronquées par l'embedding) puis « Passage: » + texte du livre.
// Un chunk dont l'augmentation est illisible n'est PAS envoyé à la vectorisation : il reste « à indexer »
// et sera retraité au prochain dépôt du PDF (ingestion reprenable). Les autres continuent.
const chunks = $('Limite (chunks par exécution)').all();
const llm = $input.all();

const str = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const list = (v, n, max) => (Array.isArray(v) ? v : []).map(x => str(x, max)).filter(Boolean).slice(0, n);

const out = [];
llm.forEach((item, i) => {
  const chunk = chunks[item.pairedItem?.item ?? i]?.json;
  if (!chunk) return;
  // Nœud Google Gemini (sortie JSON) : le texte est dans content.parts[].text
  const raw = String(item.json.text ?? (item.json.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join(''));
  let a = {};
  try { const m = raw.match(/\{[\s\S]*\}/); a = JSON.parse(m ? m[0] : raw); } catch (e) { a = {}; }

  const contexte = str(a.contexte, 400);
  const questions = list(a.questions, 5, 200);
  const motsCles = [...new Set(list(a.mots_cles, 12, 40).map(k => k.toLowerCase()))];
  const entites = (Array.isArray(a.entites) ? a.entites : [])
    .map(e => (typeof e === 'string' ? { nom: e } : e || {}))
    .map(e => ({ nom: str(e.nom, 60), type: str(e.type, 25) }))
    .filter(e => e.nom).slice(0, 12);
  const relations = (Array.isArray(a.relations) ? a.relations : [])
    .map(r => r || {})
    .map(r => ({ source: str(r.source, 60), relation: str(r.relation, 50), cible: str(r.cible, 60) }))
    .filter(r => r.source && r.relation && r.cible).slice(0, 8);
  if (!contexte || !questions.length || !motsCles.length) return;   // illisible → retraité au prochain dépôt

  const nl = chunk.content.indexOf('\n');
  const header = nl > 0 ? chunk.content.slice(0, nl) : '';
  const passage = nl > 0 ? chunk.content.slice(nl + 1) : chunk.content;
  const blocs = [header, `Context: ${contexte}`, `Keywords: ${motsCles.join(', ')}`];
  if (entites.length) blocs.push(`Entities: ${entites.map(e => (e.type ? `${e.nom} (${e.type})` : e.nom)).join('; ')}`);
  if (relations.length) blocs.push(`Relations: ${relations.map(r => `${r.source} — ${r.relation} → ${r.cible}`).join('; ')}`);
  blocs.push(`Questions this passage answers:\n${questions.map(q => `- ${q}`).join('\n')}`);
  blocs.push(`Passage:\n${passage}`);

  out.push({ json: {
    ...chunk,
    content: blocs.join('\n'),
    contexte,
    questions: questions.join(' | '),
    mots_cles: motsCles.join(', '),
    entites: entites.map(e => e.nom).join(', '),
    relations: relations.map(r => `${r.source} — ${r.relation} → ${r.cible}`).join(' | '),
    augmente: 'oui',
  } });
});
return out;
